def low(x):
    return str(x or "").lower()

def need(task_type):
    s = low(task_type or "")
    if "clean" in s:
        return "clean"
    if "heat" in s:
        return "heat"
    if "cool" in s:
        return "cool"
    return ""

def carrying(inv, target):
    if not target:
        return False
    text = low(inv)
    return bool(target in text and "nothing" not in text and "not carrying" not in text and "empty" not in text)

def has_adm(adm, prefix, target, dest, item, loc):
    for a in adm or []:
        al = low(a)
        if al.startswith(prefix) and (not target or target in al) and (not dest or dest in al) and (not item or item in al) and (not loc or loc in al):
            return True
    return False

def hook(ctx, nb):
    task = ctx.get("task") or {}
    tt = low(task.get("task_type") or ctx.get("task.task_type") or "")
    target = low(task.get("target_type") or ctx.get("task.target_type") or "")
    dest = low(task.get("destination_type") or ctx.get("task.destination_type") or "")
    need_op = need(tt)
    if not need_op:
        nb["transform_done"] = True
    else:
        act = low(val(ctx, "action.final_action", "") or val(ctx, "action.normalized", "") or val(ctx, "action.raw", ""))
        if act.startswith(need_op + " ") and target in act:
            nb["transform_done"] = True
    world = ctx.get("world") or {}
    pc = world.get("placed_count")
    if isinstance(pc, int) and pc > (nb.get("placed_count") or 0):
        nb["placed_count"] = pc
    if not need_op:
        nb["stage"] = "put_target" if carrying(world.get("inventory"), target) else "find_target"
    elif carrying(world.get("inventory"), target) and not nb.get("transform_done"):
        nb["stage"] = "transform"
    else:
        adm = ctx.get("admissible") or []
        inv = world.get("inventory") or ""
        if not carrying(inv, target):
            nb["stage"] = "wrong_inventory" if inv and "nothing" not in low(inv) and "not carrying" not in low(inv) and "empty" not in low(inv) else "find_target"
        elif need_op and not nb.get("transform_done"):
            nb["stage"] = "transform"
        else:
            target_found = bool(world.get("target_found")) or has_adm(adm, "take ", target, "", "", "")
            put_ready = has_adm(adm, "put ", target, dest, "", "")
            if target_found and not carrying(inv, target) and not nb.get("transform_done"):
                nb["stage"] = "take_target"
            elif put_ready:
                nb["stage"] = "put_target"
            else:
                nb["stage"] = "go_destination"
    return None

