def hook(ctx, nb):
    stage = nb.get("stage")
    if not stage or stage == "find_target":
        return None
    task = ctx.get("task") or {}
    tt = str(task.get("task_type") or ctx.get("task.task_type") or "").lower()
    target = str(task.get("target_type") or ctx.get("task.target_type") or "").lower()
    dest = str(task.get("destination_type") or ctx.get("task.destination_type") or "").lower()
    need_op = need(tt)
    msg = ""
    if stage == "wrong_inventory":
        msg = "You appear to be carrying a non-target item. Do not place it at the goal; clear it if needed, then search for the target type: " + target + "."
    elif stage == "take_target":
        msg = "The target " + target + " is available here. Take it now instead of continuing to search or examining unrelated objects."
    elif stage == "transform" and need_op:
        msg = "Before any put action, use the available " + need_op + " action on the " + target + ". Do not place it yet, and do not take it back after placing."
    elif stage == "put_target":
        item = val(ctx, "world.placed_items", "") or ""
        if not isinstance(item, list):
            item = [item]
        loc = val(ctx, "world.placed_locations", "") or ""
        if not isinstance(loc, list):
            loc = [loc]
        loop = bool(val(ctx, "predicates.same_action_repeated", False) or val(ctx, "predicates.same_observation_repeated", False) or val(ctx, "predicates.remaining_steps_low", False))
        if has_adm(ctx.get("admissible") or [], "put ", target, dest, item, loc) or loop:
            msg = "The correct destination is a " + dest + ". Put the " + target + " there now, then leave placed items alone."
        else:
            msg = "Carry the " + target + " to the " + dest + " and put it there; do not place it on other surfaces."
    elif stage == "go_destination":
        msg = "Now go to the " + dest + " with the " + target + ", then use the put action there. Avoid revisiting places already searched."
    if not msg:
        return None
    key = stage + "|" + msg[:80]
    if nb.get("last_hint") == key:
        return None
    nb["last_hint"] = key
    return {"message": msg}
